import { useMutation } from '@tanstack/react-query';
import { exchangeResponseDTO, PaymentRequestDTO } from '~/entities/exchange/api/dtos/types';
import { exchangeApi } from '~/entities/exchange/api/exchange-api';
import { CBDCAxiosError } from '~/shared/@types/error';
import { MutationOptions } from '~/shared/@types/query';

export const useMrmPaymentMutation = (
  options?: MutationOptions<PaymentRequestDTO, CBDCAxiosError, exchangeResponseDTO>,
) => {
  const mutation = useMutation<exchangeResponseDTO, CBDCAxiosError, PaymentRequestDTO>({
    ...options,
    mutationFn: exchangeApi.mrmPayment,
  });

  return {
    ...mutation,
  };
};
