import axios from 'axios';
import { Fragment, useRef } from 'react';
import ReactPlayer from 'react-player';
import { 처리중Context } from '~/widgets/exchange-payment-funnel/model/schemas';
import { useSetHeaderLeft } from '~/widgets/sub-layout/use-sub-layout';
import { useExchangeProcessVideo } from '~/features/load-video/use-exchange-process-video';
import { PaymentRequestDTO } from '~/entities/exchange/api/dtos/types';
import { useMrmPaymentMutation } from '~/entities/exchange/api/hooks/use-mrm-payment-mutation';
import { usePaymentMutation } from '~/entities/exchange/api/hooks/use-payment-mutation';
import { useResultSearchMutation } from '~/entities/exchange/api/hooks/use-result-search-mutation';
import { PhaseType } from '~/entities/exchange/model/constants';
import { ConfirmInfo } from '~/entities/exchange-input-confirm/ui/confirm-info';
import { paymentStatusHandlers } from '~/entities/exchange-process/lib/use-transaction-status';
import { getExchangeTransactionLabel } from '~/entities/wallet/lib/get-trnsc-type-label';
import { MPMQrScanType, StatusType } from '~/shared/api/dtos/enums';
import i18n from '~/shared/i18n/i18n';
import { useAlertDialog } from '~/shared/lib/hooks/use-alert-dialog';

type ProcessPageProps = {
  context: 처리중Context;
  onNext: (params: { trnscId: string; reqAliasNm: string; amt: string }) => void;
  onError: (error: Error) => void;
};

type PaymentErrorSource = {
  exMessage?: unknown;
  message?: unknown;
};

const extractPaymentErrorMessage = (result: unknown): string => {
  const source = axios.isAxiosError<PaymentErrorSource>(result) ? result.response?.data : result;

  if (source && typeof source === 'object') {
    const { exMessage, message } = source as PaymentErrorSource;

    if (typeof exMessage === 'string' && exMessage.trim()) {
      return exMessage;
    }

    if (typeof message === 'string' && message.trim()) {
      return message;
    }
  }

  return result instanceof Error ? result.message : '결제 실패';
};

export const ProcessPage = ({ onNext, onError, context }: ProcessPageProps) => {
  const { movUrl } = useExchangeProcessVideo({ trnscTypeCd: context.trnscTypeCd });
  const { mutateAsync: payment } = usePaymentMutation({ throwOnError: false });
  const { mutateAsync: mrmPayment } = useMrmPaymentMutation({ throwOnError: false });
  const { mutateAsync: resultSearch } = useResultSearchMutation({ throwOnError: false });
  const { openAlertDialog } = useAlertDialog();
  const count = useRef<number>(0);

  /**
   * 결제 요청 처리 함수
   */
  const requestPayment = async () => {
    if (context.mpmType === MPMQrScanType.고정형) {
      const mrmParams: PaymentRequestDTO = {
        tbPayMastr: {
          txCd: context.aliasNm ?? '',
          vouchId: context.vouchId ?? '',
          amt: context.trnscAmt ?? '',
          aliasNm: context.aliasNm ?? '',
          placeSecret: context.placeNm ?? '',
          placeBankCode: context.walletInsttCd ?? '',
          vouchAddres: context.vouchAddres ?? '',
          vouchBankCode: context.vouchBankCode ?? '',
          vouchTypeNm: context.vouchTypeNm ?? '',
          insttWalletAdres: context.insttWalletAdres ?? '',
          vouchNm: context.vouchNm ?? '',
          vouchTyNm: context.vouchTyNm ?? '',
          vouchTyCd: context.vouchTyCd ?? '',
          placeId: context.placeId ?? '',
        },
      };

      return await mrmPayment(mrmParams);
    }
    const params: PaymentRequestDTO = {
      tbPayMastr: {
        vouchId: context.vouchId ?? '',
        txCd: context.aliasNm ?? '',
        placeSecret: context.placeNm ?? '',
        placeBankCode: context.walletInsttCd ?? '',
        vouchAddres: context.vouchAddres ?? '',
        vouchBankCode: context.vouchBankCode ?? '',
        vouchTypeNm: context.vouchTypeNm ?? '',
        insttWalletAdres: context.insttWalletAdres ?? '',
        vouchNm: context.vouchNm ?? '',
        vouchTyNm: context.vouchTyNm ?? '',
        vouchTyCd: context.vouchTyCd ?? '',
      },
    };
    return await payment(params);
  };

  /**
   * 비디오 종료 후 호출되는 이벤트 핸들러
   */
  const handleEventChange = async () => {
    try {
      // 결제 API 호출
      const requestResult = await requestPayment();

      // 트랜잭션 ID가 문자열인 경우 폴링 시작
      if (requestResult && typeof requestResult.requestId === 'string') {
        // await pollTransactionStatus({
        //   transactionId: requestResult,
        //   resultSearch,
        //   openAlertDialog,
        //   onNext,
        //   onError,
        //   counter: count,
        // });
        // const amt = requestResult.payload?.vouchAmt || '0';
        const amt = '0';
        const status = requestResult?.status as StatusType | undefined;
        const errorMessage = status === StatusType.실패 ? extractPaymentErrorMessage(requestResult) : undefined;
        const handlers = paymentStatusHandlers(
          requestResult.requestId,
          requestResult.payload?.aliasNm ?? context.aliasNm ?? '',
          {
            onNext,
            amt,
            errorMessage,
          },
        );

        // Execute the appropriate handler based on status or use default
        handlers[status as keyof typeof handlers]?.();
      } else {
        const error = new Error('결제 오류');
        onError(error);
      }
    } catch (error) {
      const normalizedError = new Error(extractPaymentErrorMessage(error));
      openAlertDialog({
        message: normalizedError.message,
        onConfirmClick: () => {
          if (window.ReactNativeWebView) {
            window.ReactNativeWebView.postMessage(JSON.stringify({ type: 'CLOSE_POPUP' }));
          } else {
            window.close();
          }
        },
      });

      console.error(normalizedError);
    }
  };

  useSetHeaderLeft(<></>);

  const transactionLabel = getExchangeTransactionLabel(context.trnscTypeCd);

  return (
    <div className="wrap bgw">
      <div className="content sub">
        <ConfirmInfo amount={Number(context.trnscAmt)} phase={PhaseType.Process} transactionLabel={transactionLabel}>
          <Fragment>{i18n.t('text:fromX', { x: context?.placeNm })}</Fragment>
        </ConfirmInfo>
        <div className="result-area">
          <div className="process">
            <div className="process-mov">
              <ReactPlayer
                url={movUrl}
                width="250px"
                height="250px"
                playing={true}
                muted={true}
                controls={false}
                loop={false}
                onEnded={handleEventChange}
                config={{
                  file: {
                    attributes: {
                      playsInline: true, // Prevents fullscreen on iOS
                    },
                  },
                }}
              />
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};
